head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.addTab = function(label, tabId, src) {
    var tabOpt = {
        label: label,
        closable: true
    };
    var contOpt = {
        frameMode: "wframe",
        scope: true,
        src: src,
        alwaysDraw: false,
        title: tabId
    };
    tac_main.addTab(tabId, tabOpt, contOpt);
};
scwin.btn_trigger1_onclick = function(e) {
    var tabId = "tab" + scwin.tabIndex;
    var label = tabId;
    var src = "gridView_selectbox_chooseOption_WEFF-624_(WSQ-3973)_sub1" + ".xml";
    scwin.addTab(label, tabId, src);
    scwin.tabIndex++;
};
scwin.btn_trigger2_onclick = function(e1) {
    var tabId = "tab" + scwin.tabIndex;
    var label = tabId;
    var src = "gridView_selectbox_chooseOption_WEFF-624_(WSQ-3973)_sub2" + ".xml";
    scwin.addTab(label, tabId, src);
    scwin.tabIndex++;
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'btn_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'tac_main_tab_tab1_tabHTML').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'tac_main_contents_tab1_body_gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('G_'+$p.id+'tac_main_contents_tab1_body_gridView1___selectbox_col1_itemTable_0').innerText === WebSquare.language.getMessage('SelectBox_choose')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.tabIndex = 1;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
